from pathlib import Path
from zipfile import ZipFile,ZIP_DEFLATED
import json,hashlib,subprocess
w=Path('work').resolve();p=w/'hekate-nova-pro-v34-alpha6';o=w.parent/'outputs';sha=lambda b:hashlib.sha256(b).hexdigest()
for n in ('nova34a6-tv-driver-check.json','nova34a6-tv-integration.json','nova34a6-header-check.json','nova34a6-copy-check.json','nova34a6-partition-check.json','nova34a6-fatfs-check.json'):assert json.loads((w/n).read_text())['passed']
assert 'PASS' in json.loads((w/'nova34a6-tv-lifecycle-check.json').read_text())['result']
note="Hekate Nova Pro v34 alpha 6 — correctif dock / reprise vidéo\n\nRapports utilisateur run-021 à run-024 : les tentatives sans réponse à Discover Identity démarrent avec un ancien état DP actif (4182). La tentative partie de 4000 identifie le dock, puis le lien HBR2 perd son égalisation après le démarrage du flux (77/81 devient 11/80). La TV reste sans signal ; l'extinction de la LED résulte de l'arrêt du pilote après échec. Ces observations orientent les corrections, sans établir une validation matérielle de celles-ci.\n\n- Nettoyage d'un mode DisplayPort hérité avant de redemander l'identité : commande Exit DP existante, attente de fin puis délai de stabilisation habituel. Aucun reset du contrôleur PD ni changement des tensions.\n- Le premier lien conserve le réglage précédent. S'il s'entraîne mais ne synchronise pas la vidéo, reprise du seul lien vidéo à 2,7 puis 1,62 Gbit/s, dans les limites du récepteur. La session du dock est conservée pendant ces replis ; pas de boucle infinie.\n- Vérification fraîche de la récupération d'horloge, de l'égalisation, du verrouillage des symboles, de l'alignement et de la synchronisation du flux ; un ancien bit de succès ne suffit pas.\n- Maintien des correctifs alpha5 : service TV pendant les opérations longues, image transmise après composition, journaux différés pour éviter les accès SD concurrents, jusqu'à trois sessions espacées, arrêts de sécurité et commandes manuelles conservés.\n\nContrôles PC : 54 scénarios du service TV ; 429 assertions sur les fonctions réelles du pilote (376 synchronisation, 30 replis, 16 mode hérité, 7 calculs 720p60), intégration aux maintenances/attentes de boutons ; 3664 assertions de partitionnement, 246 de copie, 147 avec FatFs réel sur FAT32/exFAT virtuels. Compilation ARM et en-têtes vérifiés. Aucun test HDMI ou écriture sur carte physique ici.\n\nInstaller bootloader et utiliser le payload de ce pack ; conserver ses réglages existants. Activer la détection TV automatique dans Nyx si souhaité. Tester d'abord un démarrage directement sur dock officiel, puis un retrait/remise, avant toute opération longue. En cas d'échec, transmettre last-run.txt et l'historique run-*.txt de bootloader/tv-test : le journal doit indiquer 34-alpha6 et mentionner les replis de débit lorsqu'ils ont lieu. Ne pas partitionner une SD sans sauvegarde de ses données.\n\nLe pack 8GB expérimental est uniquement destiné aux consoles physiquement modifiées en RAM. Aucun upload GitHub de cette alpha ; validation sur console requise.\n"
(o/'LIRE-MOI-NOVA34-ALPHA6.txt').write_text(note,encoding='utf-8');(p/'ASSISTANT-V34-ALPHA6.txt').write_text(note,encoding='utf-8')
translations={'fr':'Maintien du service TV pendant les opérations longues, rafraîchissement après chaque image terminée, journaux TV différés pour éviter tout accès SD réentrant. Attentes de boutons coopératives. Réglages et arrêts matériels conservés. Validation matérielle à effectuer.','en':'Keep TV serviced during long operations, present completed frames, defer TV logs to avoid reentrant SD access, and service physical-button waits. Preserve settings and hardware shutdown guards. Physical validation pending.','es':'Servicio TV durante operaciones largas y esperas de botones. Presentación de imágenes completas y registros diferidos sin acceso SD simultáneo. Ajustes y protecciones conservados. Falta validación física.','it':'Servizio TV durante operazioni lunghe e attese dei pulsanti. Immagini complete e registri differiti senza accesso SD rientrante. Impostazioni e protezioni mantenute. Verifica hardware da eseguire.','de':'TV-Dienst während langer Vorgänge und Tastenwartezeiten. Fertige Bilder übertragen, Protokolle ohne rekursiven SD-Zugriff verzögern. Einstellungen und Schutzabschaltungen bleiben erhalten. Hardwareprüfung ausstehend.','pt':'Serviço TV durante operações longas e esperas de botões. Imagens completas e registos adiados sem acesso SD recursivo. Definições e proteções mantidas. Validação física pendente.','ru':'Обслуживание TV во время длительных операций и ожидания кнопок. Передача готовых кадров и отложенная запись журналов без повторного доступа к SD. Настройки и защитные отключения сохранены. Проверка на консоли ожидается.','zh-CN':'长时间操作和等待按键时保持 TV 服务，完成画面后更新输出，延迟保存日志以避免重复访问 SD。保留设置和硬件保护，仍需实机验证。'}
for key,value in {'fr': ' Jusqu’à trois tentatives espacées après échec de connexion ; aucun reset PD forcé et arrêt manuel prioritaire.', 'en': ' Up to three spaced attempts after connection failure; no forced PD reset and manual stop takes priority.', 'es': ' Hasta tres intentos espaciados tras fallo; sin reinicio PD forzado y parada manual prioritaria.', 'it': ' Fino a tre tentativi distanziati dopo un errore; nessun reset PD forzato e arresto manuale prioritario.', 'de': ' Bis zu drei zeitversetzte Versuche nach Verbindungsfehler; kein erzwungener PD-Reset, manueller Stopp hat Vorrang.', 'pt': ' Até três tentativas espaçadas após falha; sem reset PD forçado e paragem manual prioritária.', 'ru': ' До трёх попыток с паузами после ошибки связи; без принудительного сброса PD, ручная остановка имеет приоритет.', 'zh-CN': ' 连接失败后最多间隔重试三次，不强制重置 PD，手动停止优先。'}.items():translations[key]+=value
for key,value in {'fr':' Confirmation fraîche de synchronisation vidéo (attente bornée à 1 s) ; échec explicite sans synchronisation/AUX/HPD. Numéro de journal corrigé.', 'en':' Require fresh video stream sync within 1 s; fail explicitly on missing sync/AUX/HPD. Correct log version.', 'es':' Confirmación nueva de sincronización en 1 s; error explícito sin sincronización/AUX/HPD. Versión del registro corregida.', 'it':' Conferma aggiornata della sincronizzazione entro 1 s; errore esplicito senza sincronizzazione/AUX/HPD. Versione registro corretta.', 'de':' Frische Videosynchronisation innerhalb 1 s erforderlich; Fehler bei fehlendem Sync/AUX/HPD. Protokollversion korrigiert.', 'pt':' Confirmação atual da sincronização em 1 s; erro explícito sem sincronização/AUX/HPD. Versão do registo corrigida.', 'ru':' Требуется свежее подтверждение синхронизации за 1 с; явная ошибка при отсутствии синхронизации/AUX/HPD. Версия журнала исправлена.', 'zh-CN':' 最多等待 1 秒获取最新视频同步确认；同步、AUX 或 HPD 失败时明确报错，修正日志版本。'}.items():translations[key]+=value
for key,value in {'fr':' Alpha6 : sortie contrôlée du mode DP hérité avant identification ; repli du seul lien vidéo vers HBR/RBR après perte de synchronisation, avec contrôle frais de toutes les voies. 429 assertions du pilote et 54 scénarios du service réussis sur PC ; essai console requis.', 'en':' Alpha6: exit inherited DP mode before discovery; retry only the video link at HBR/RBR after stream-sync failure, checking fresh lane status. 429 driver assertions and 54 service scenarios passed on PC; console testing required.', 'es':' Alpha6: salir del modo DP heredado antes de identificar el dock; reintentar el enlace de vídeo a HBR/RBR tras un fallo de sincronización, comprobando las vías. 429 comprobaciones del controlador y 54 escenarios de servicio superados en PC; falta prueba en consola.', 'it':' Alpha6: uscita controllata dalla modalità DP ereditata prima di identificare il dock; ripetizione del collegamento video a HBR/RBR dopo mancata sincronizzazione, verificando le linee. 429 verifiche del driver e 54 scenari superati su PC; prova console necessaria.', 'de':' Alpha6: geerbten DP-Modus vor der Erkennung verlassen; bei fehlender Videosynchronisation nur den Videolink mit HBR/RBR neu starten und aktuelle Lane-Statuswerte prüfen. 429 Treiberprüfungen und 54 Dienstszenarien auf PC bestanden; Konsolentest erforderlich.', 'pt':' Alpha6: saída controlada do modo DP herdado antes de identificar o dock; nova tentativa apenas do enlace de vídeo em HBR/RBR após falha de sincronização, verificando as vias. 429 verificações do controlador e 54 cenários aprovados no PC; falta teste na consola.', 'ru':' Alpha6: управляемый выход из унаследованного режима DP до обнаружения дока; повтор видеолинии на HBR/RBR при потере синхронизации с проверкой текущего состояния каналов. На ПК пройдено 429 проверок драйвера и 54 сценария службы; нужен тест на консоли.', 'zh-CN':' Alpha6：识别底座前受控退出遗留 DP 模式；视频同步失败时仅以 HBR/RBR 重试视频链路，并读取各通道最新状态。PC 已通过 429 项驱动断言和 54 个服务场景，仍需主机实测。'}.items():translations[key]+=value
reports=['nova34a6-tv-driver-check.json','nova34a6-tv-lifecycle-check.json','nova34a6-tv-integration.json','nova34a6-header-check.json','nova34a6-copy-check.json','nova34a6-partition-check.json','nova34a6-fatfs-check.json']
summary={}
for suffix in ('','-8GB'):
 with ZipFile(o/('hekate-nova-pro-v34-alpha4'+suffix+'.zip'))as z:files={n:z.read(n)for n in z.namelist()if not n.endswith('/')and not n.startswith('hekate_nova_pro_')and n not in ('BUILD-INFO.json','BUNDLE-MANIFEST.json')}
 for n in ('nyx.bin','libsys_lp0.bso','libsys_minerva.bso'):files['bootloader/sys/'+n]=(p/'output'/n).read_bytes()
 payload=bytearray((p/'output/hekate.bin').read_bytes());assert not payload[0x122]&1
 if suffix:payload[0x122]|=1
 name='hekate_nova_pro_6.5.5_v34_alpha6'+('_8GB_EXPERIMENTAL'if suffix else'')+'.bin';files[name]=files['bootloader/update.bin']=files['bootloader/payloads/'+name]=bytes(payload)
 files['LIRE-MOI.txt']=note.encode();files['documentation/TV-V34-ALPHA6.txt']=note.encode()
 for code,t in translations.items():files['documentation/changelogs/CHANGELOG-NOVA34-ALPHA6-'+code+'.md']=('# Hekate Nova Pro v34 alpha 6\n\n'+t+'\n').encode()
 for n in reports:files['verification/'+n]=(w/n).read_bytes()
 files['BUILD-INFO.json']=json.dumps({'version':'34-alpha6','variant':'8GB-experimental'if suffix else'standard','compiled':True,'physical_console_test':False,'tv_long_operations':True},indent=2).encode()
 files['BUNDLE-MANIFEST.json']=json.dumps({n:sha(b)for n,b in files.items()},indent=2).encode()
 target=o/('hekate-nova-pro-v34-alpha6'+suffix+'.zip');assert not target.exists()
 with ZipFile(target,'w',ZIP_DEFLATED,compresslevel=6)as z:
  for n,b in sorted(files.items()):z.writestr(n,b)
 with ZipFile(target)as z:assert z.testzip()is None
 summary[target.name]={'bytes':target.stat().st_size,'sha256':sha(target.read_bytes())}
# Complete source and unchanged standalone diagnostic dependencies.
with ZipFile(o/'hekate-nova-pro-v34-alpha4-sources.zip')as z:files={n:z.read(n)for n in z.namelist()if not n.endswith('/')and not n.startswith('hekate-nova-pro-v34-alpha4/')}
for f in p.rglob('*'):
 if f.is_file()and not any(x in ('build','output','.git','__pycache__')for x in f.relative_to(p).parts)and f.name not in ('payload_00.h','payload_01.h'):files['hekate-nova-pro-v34-alpha6/'+f.relative_to(p).as_posix()]=f.read_bytes()
for f in w.glob('*nova34a6*.py'):files['build-tools/'+f.name]=f.read_bytes()
for f in (w/'nova34a6-tv-tests').rglob('*'):
 if f.is_file()and f.suffix not in ('.exe',):files['build-tools/nova34a6-tv-tests/'+f.relative_to(w/'nova34a6-tv-tests').as_posix()]=f.read_bytes()
